                    {{#each glossary}}{{#regexReplace "^.*?<br\s*/?>" ""}}{{{formatGlossaryPlain ../dictionary .}}}{{/regexReplace}}{{#unless @last}}<br>{{/unless}}{{/each}}{{#unless @last}}<br>{{/unless}}
